```solidity
import "witnet-solidity-bridge/contracts/interfaces/IWitnetPriceRouter.sol`

contract MyContract {

  function lastBtcUsdValue() external view returns (int, uint, uint) {
     return IWitnetPriceRouter(<0x-address of WitnetPriceRouter>).valueFor(bytes32(0x24beead4));
  }

  function lastEthUsdValue() external view returns (int, uint, uint) {
     return IWitnetPriceRouter(<0x-address of WitnetPriceRouter>).valueFor(bytes32(0x3d15f701));
  }
}
